from pathlib import Path
import json, html
root=Path(__file__).resolve().parents[1]
entries=json.loads((root/'server/packs/after-dark-v09.json').read_text(encoding='utf-8'))['entries']
payload=json.dumps(entries,ensure_ascii=False).replace('</','<\\/')
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ECKEY THUMP — After Dark Content Review</title><style>
:root{font-family:system-ui,-apple-system,Segoe UI,sans-serif;background:#10091c;color:#fff5ff}*{box-sizing:border-box}body{margin:0;padding:26px 16px 60px;max-width:1300px;margin-inline:auto}h1{font-size:clamp(2rem,6vw,4rem);line-height:1;margin:0;color:#ffd56a;text-shadow:2px 3px #aa35a8}p{color:#cebfdb;line-height:1.55}.head{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}.pill{padding:8px 14px;border-radius:22px;border:1px solid #79598f;color:#ffdbb2}.controls{display:flex;flex-wrap:wrap;gap:9px;margin:24px 0}.controls input,.controls select,.controls button{font:inherit;color:#fff;background:#301b45;border:2px solid #7a568f;padding:12px;border-radius:12px;min-height:46px}.controls input{flex:2;min-width:200px}.controls select{flex:1;min-width:140px}.controls button{cursor:pointer;background:#ffbf54;color:#1a1020;border-color:#ffdd7a;font-weight:800}.layout{display:grid;grid-template-columns:repeat(auto-fill,minmax(295px,1fr));gap:14px}.card{background:linear-gradient(145deg,#37204d,#1b1030);border:2px solid #704a8b;padding:17px;border-radius:16px;min-height:171px;display:flex;flex-direction:column;gap:11px}.card.cheeky{border-color:#e673c8}.card.adult{border-color:#ffa05c}.meta{font-weight:850;font-size:.76rem;letter-spacing:.08em;color:#ffcf6f}.copy{flex:1;line-height:1.42;font-size:1.04rem}.actions{display:flex;gap:8px;align-items:center}.actions button{cursor:pointer;border-radius:7px;padding:7px 10px;border:1px solid #79598f;background:#2c1740;color:#fff;font-weight:700}.actions button.bad{background:#713039}.actions button.good{background:#205d4f}small{color:#b5aac1}.stats{margin:18px 0;color:#eee}button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #f7d977;outline-offset:3px}.empty{padding:40px;font-size:1.2rem;color:#ffdc97}a{color:#ffe091}
</style></head><body>
<div class="head"><div><div class="pill" style="display:inline-block;margin-bottom:14px">PRIVATE EDITORIAL REVIEW • NOT CUSTOMER-FACING</div><h1>ECKEY THUMP<br>AFTER DARK</h1><p>Explore 1,200 new comedy-content entries. Mark weak ones for rewriting and export your editorial decisions. Original editorial draft — not playtest-approved.</p></div><div class="pill">1,200 NEW ENTRIES</div></div>
<div class="controls"><input id="search" placeholder="Search jokes and prompts…" aria-label="Search content"><select id="tier" aria-label="Humour rating"><option value="">All ratings</option><option value="cheeky">Cheeky</option><option value="adult">Adult</option><option value="clean">Clean</option></select><select id="kind" aria-label="Challenge type"><option value="">All challenge types</option></select><select id="mark" aria-label="Editorial decision"><option value="">All decisions</option><option value="keep">Keep</option><option value="rewrite">Rewrite</option><option value="unreviewed">Unreviewed</option></select><button id="random">Random 12</button><button id="export">Export decisions</button></div><div class="stats" id="stats" aria-live="polite"></div><main class="layout" id="cards"></main>
<script>const DATA=__PAYLOAD__;
const $=id=>document.getElementById(id);const byId=new Map(DATA.map(x=>[x.id,x]));
const safe=(s)=>String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]));
const KEY='eckey-review-v09';let decisions={};try{decisions=JSON.parse(localStorage.getItem(KEY)||'{}')}catch{};
for(const kind of [...new Set(DATA.map(x=>x.kind))].sort()){const option=document.createElement('option');option.value=kind;option.textContent=kind;$('kind').append(option)};
function filtered(){const q=$('search').value.trim().toLowerCase(),tier=$('tier').value,kind=$('kind').value,mark=$('mark').value;
 return DATA.filter(x=>(!tier||x.rating===tier)&&(!kind||x.kind===kind)&&(!q||x.text.toLowerCase().includes(q)||x.id.includes(q))&&(!mark||(mark==='unreviewed'?!decisions[x.id]:decisions[x.id]===mark)))}
let randomSubset=null;
function render(){const all=filtered();const items=randomSubset?randomSubset.filter(x=>all.includes(x)):all;
 const reviewed=Object.keys(decisions).length,keeps=Object.values(decisions).filter(x=>x==='keep').length,revisions=Object.values(decisions).filter(x=>x==='rewrite').length;
 $('stats').textContent=`${items.length} showing • ${reviewed} reviewed • ${keeps} approved • ${revisions} flagged for rewriting • ${DATA.length-reviewed} unreviewed`;
 $('cards').innerHTML=items.slice(0,300).map(x=>`<article class="card ${x.rating}"><span class="meta">${safe(x.rating.toUpperCase())} · ${safe(x.kind)}</span><div class="copy">${safe(x.text)}</div><small>${safe(x.id)}</small><div class="actions"><button data-id="${safe(x.id)}" data-mark="keep" class="${decisions[x.id]==='keep'?'good':''}" aria-label="Approve ${safe(x.id)}">✓ Keep</button><button data-id="${safe(x.id)}" data-mark="rewrite" class="${decisions[x.id]==='rewrite'?'bad':''}" aria-label="Flag ${safe(x.id)} for rewrite">✎ Rewrite</button></div></article>`).join('')||'<div class="empty">No content matches these filters.</div>';
 if(items.length>300)$('stats').textContent+=' • Display capped at 300; filter to inspect more.';
}
for(const id of ['search','tier','kind','mark']) $(id).addEventListener('input',()=>{randomSubset=null;render()});
$('random').addEventListener('click',()=>{randomSubset=filtered().sort(()=>Math.random()-.5).slice(0,12);render()});
$('cards').addEventListener('click',event=>{const button=event.target.closest('[data-id]');if(!button)return;const id=button.dataset.id,mark=button.dataset.mark; if(decisions[id]===mark)delete decisions[id];else decisions[id]=mark;localStorage.setItem(KEY,JSON.stringify(decisions));render()});
$('export').addEventListener('click',()=>{const a=document.createElement('a'),blob=new Blob([JSON.stringify({pack:'eckey-after-dark-09',savedAt:new Date().toISOString(),decisions},null,2)],{type:'application/json'});a.href=URL.createObjectURL(blob);a.download='ECKEY-THUMP-v09-editorial-decisions.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),3000)});
render();</script></body></html>'''.replace('__PAYLOAD__',payload)
(root/'CONTENT-REVIEW.html').write_text(page,encoding='utf-8')
print('review file',len(page))
